export type SocketState = "closed" | "connecting" | "open";
export interface HeldRun { id: string; name?: string; packTitle?: string }
export interface Snapshot { unit?: number; words?: { unit: string }; score?: { text: string }; latest?: { text: string } | null; clocks?: Array<{ id: string; label: string; kind: "timer" | "stopwatch"; seconds: number | null; status: string; elapsedMs: number }>; standings?: Array<{ name: string; points: number; place: number }>; counters?: Array<{ id: string; label: string; value: number }>; resources?: Array<{ id: string; label: string; value: number; max: number | null }>; at?: string; offer?: Offer }
export interface DeckState {
  session: SessionState;
  socket: SocketState;
  runs: HeldRun[];
  any: boolean;
  pinned: string | null;
  attached: string | null;
  snapshot: Snapshot | null;
  flash: { ref: string; ok: boolean; say?: string; until: number } | null;
}
export type Tone = "live" | "dim" | "refuse";
export interface Face { title: string; tone: Tone; when?: string }
export function initial(): DeckState;
export function attachedRun(state: DeckState): string | null;   // pinned if held, else the only held run, else null
export function nextFace(state: DeckState): Face;
export function pressFace(state: DeckState, target: PressTarget): Face;
export function undoFace(state: DeckState): Face;
export function runFace(state: DeckState): Face;
export function metricFace(state: DeckState, field: MetricField, now: number): Face;
export type PressTarget = { kind: "roll" } | { kind: "move"; id: string } | { kind: "answer"; preset: string; value: string };
export type MetricField = "score" | "unit" | "clock" | "latest" | "leader" | { counter: string } | { resource: string };
